CREATE OR REPLACE PROCEDURE place_order(
    p_customer_id INTEGER,
    p_product_id INTEGER,
    p_quantity INTEGER
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_stock INTEGER;
BEGIN
    SELECT stock_quantity INTO v_stock FROM inventory WHERE product_id = p_product_id;
    IF v_stock IS NULL OR v_stock < p_quantity THEN
        RAISE EXCEPTION 'Insufficient stock for product %', p_product_id;
    END IF;
    INSERT INTO orders (customer_id, product_id, quantity, status) VALUES (p_customer_id, p_product_id, p_quantity, 'pending');
    UPDATE inventory SET stock_quantity = stock_quantity - p_quantity WHERE product_id = p_product_id;
    COMMIT;
END;
$$;
